#include <iostream>
#include <vector>
#include <algorithm>
#include <cstring>
#include <climits>
using namespace std;
typedef long long LL;
typedef unsigned long long ULL;
typedef long double LD;
typedef pair<int,int> PII;
typedef vector<int> VI;
typedef vector<LL> VL;
typedef vector<PII> VPII;
typedef pair<LL,LL> PLL;
typedef vector<PLL> VPLL;
const int SIZE = 1e6+10;
const int INF = 1034567890;
const int MAX_EDGE_NUM = 1000000;
const int MAX_NODE_NUM = 100000;
struct EDGE{
    int y,c,v,ty;
    EDGE(int _y=0,int _c=0,int _v=0,int ty=0):y(_y),c(_c),v(_v),ty(ty){}
}es[MAX_EDGE_NUM];
vector<int>e[MAX_NODE_NUM];
int C,d;
int en;
int EE;
void flow_clear(int _EE){
    EE=_EE;
    for(int i=0;i<=EE;i++)e[i].clear();
    en=0;
}
void add_edge(int x,int y,int c,int v,int _ty){
    e[x].push_back(en);
    es[en++]=EDGE(y,c,v,_ty);
    e[y].push_back(en);
    if(_ty==1){
        es[en++]=EDGE(x,0,-C+d,_ty);
    }
    else{
        es[en++]=EDGE(x,0,-v,_ty);
    }
}
int mi[MAX_NODE_NUM],lt[MAX_NODE_NUM],bfs[10000000],used[MAX_NODE_NUM];
int flow(){
    for(int i=0;i<=EE;i++)mi[i]=INF,used[i]=0;
    mi[EE]=INF;
    bfs[0]=0;
    mi[0]=0;
    int rr=1;
    for(int i=0;i<rr;i++){
        int x=bfs[i];
        used[x]=0;
        for(int j=0;j<(int)e[x].size();j++){
            int r=e[x][j];
            if(es[r].c>0&&mi[x]+es[r].v<mi[es[r].y]){
                mi[es[r].y]=mi[x]+es[r].v;
                lt[es[r].y]=r;
                if(!used[es[r].y]){
                    used[es[r].y]=1;
                    bfs[rr++]=es[r].y;
                }
            }
        }
    }
    if(mi[EE]==INF)return -1;
    int now=EE;
    while(now){
        int r=lt[now];
        if(es[r].ty==1){
            if((r&1)==1){
                es[r].v+=2*d;
                es[r^1].v-=2*d;
            }
            else{
                es[r].v+=2*d;
                es[r^1].v-=2*d;
            }
        }
        es[r].c--;
        es[r^1].c++;
        now=es[r^1].y;
    }
    return mi[EE];
}
int solve(int nn){
    int v=0;
    for(int i=0;i<nn;i++)v+=flow();
    return v;
}
int main(){
    int n,m,k;
    cin>>n>>m>>k>>C>>d;
    flow_clear(n*100+1);
    for(int i=1;i<=k;i++){
        int x;
        cin>>x;
        add_edge(0,x,1,0,0);
    }
    for(int i=1;i<=99;i++){
        add_edge(1+i*n,100*n+1,INF,0,0);
    }
    for(int i=1;i<=n;i++){
        for(int j=1;j<=99;j++){
            add_edge(i+(j-1)*n,i+j*n,INF,C,0);
        }
    }
    for(int i=1;i<=m;i++){
        int x,y; cin>>x>>y;
        for(int j=1;j<=99;j++){
            add_edge(x+(j-1)*n,y+j*n,INF,C+d,1);
            add_edge(y+(j-1)*n,x+j*n,INF,C+d,1);
        }
    }
    cout<<solve(k)<<'\n';
    return 0;
}
